<?php declare(strict_types=1); $e=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Safeguarding report</title></head><body><main><h1>Confidential safeguarding report</h1><p>Report only information necessary to protect safety. Narratives are encrypted and visible only to the assigned MFA-enrolled specialist.</p><?php if($error!==''):?><p role="alert"><?= $e($error) ?></p><?php endif;?><?php if($submitted):?><p role="status">Report submitted. The assigned specialist has received the case in their restricted queue.</p><?php else:?><form method="post" action="/admin/safeguarding/report"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><label>Category<select name="case_type" required><?php foreach(['consent_concern','coercion_or_exploitation','trafficking_concern','minor_safety_concern','nonconsensual_content','threat_or_harassment','privacy_or_data_risk','other'] as $v):?><option value="<?= $e($v) ?>"><?= $e($v) ?></option><?php endforeach;?></select></label><label>Severity<select name="severity" required><?php foreach(['low','medium','high','critical'] as $v):?><option value="<?= $e($v) ?>"><?= $e($v) ?></option><?php endforeach;?></select></label><label>Assigned MFA specialist<select name="assigned_to" required><?php foreach($specialists as $s):?><option value="<?= $e($s['id']) ?>"><?= $e($s['email']) ?></option><?php endforeach;?></select></label><label>Summary<input name="summary" minlength="10" maxlength="1000" required></label><label>Details<textarea name="details" minlength="20" maxlength="10000" required></textarea></label><label>Related reference (optional)<input name="subject_reference" maxlength="1000"></label><button>Submit confidential report</button></form><?php endif;?></main></body></html>